def airline(callsign: str | None) -> dict | None:
    """The airline a callsign belongs to: three letters then a flight number (ANZ123, QFA1)."""
    m = re.match(r"([A-Z]{3})\d", str(callsign or "").strip().upper())
    hit = AIRLINES.get(m.group(1)) if m else None
    return {"code": m.group(1), "name": hit[0], "country": hit[1], "iata": hit[2]} if m and hit else None
